/** Paths that are gated and must never be crawled or indexed. */
const CRAWLER_DISALLOW = ["/admin", "/api/", "/gallery", "/v/", "/whoami", "/health"];

/**
 * `robots.txt` for the canonical app host: crawl the product pages, stay out of
 * everything that requires an identity.
 */
function publicRobots(origin: string): string {
  return [
    `# ${SITE.name} — public product site.`,
    "# Everything not listed below requires a signed-in identity and is never indexed.",
    `# AI agents and answer engines: ${origin}/llms.txt is the machine-readable summary,`,
    `# and ${origin}/llms-full.txt is the full text of the home page and guide.`,
    "",
    "User-agent: *",
    ...CRAWLER_DISALLOW.map((p) => `Disallow: ${p}`),
    "Allow: /",
    "",
    `Sitemap: ${origin}/sitemap.xml`,
    "",
  ].join("\n");
}

/** Disallow-everything `robots.txt`, with the reason spelled out for a human reader. */
function closedRobots(reason: string, origin: string): string {
  return [`# ${reason}`, `# The public site is ${origin}`, "", "User-agent: *", "Disallow: /", ""].join(
    "\n"
  );
}

export type RobotsAudience = "public" | "content" | "non-canonical";

export function robotsTxt(env: Pick<Env, "PUBLIC_BASE_URL">, audience: RobotsAudience): string {
  const origin = siteOrigin(env);
  if (audience === "content") {
    return closedRobots(
      "Artifact content origin. Every artifact here is access-controlled — nothing is public.",
      origin
    );
  }
  if (audience === "non-canonical") {
    return closedRobots("Non-canonical host (preview/staging). Not for indexing.", origin);
  }
  return publicRobots(origin);
}

/**
 * The two paths `security.txt` is served from. RFC 9116 makes
 * `/.well-known/security.txt` the canonical location and keeps the top-level
 * `/security.txt` as the legacy one researchers and scanners still try first;
 * both are listed as `Canonical` in the body, so finding either one proves the
 * other is not somebody else's.
 *
 * Both belong to the APP host (`MANAGEMENT_PATHS`/`MANAGEMENT_PREFIXES` in
 * src/host.ts). A content origin must 404 them rather than answer, for the
 * reason it 404s every other product surface — and, more to the point here, the
 * app host must not 302 `/security.txt` at the content host the way it does an
 * unknown path, which is what shipped before this and left the file findable at
 * neither origin.
 */
export const SECURITY_TXT_PATHS = ["/.well-known/security.txt", "/security.txt"] as const;

/** Private reporting channel and full policy — the same two links SECURITY.md gives. */
const SECURITY_ADVISORY_URL = `${SOURCE_URL}/security/advisories/new`;
const SECURITY_POLICY_URL = `${SOURCE_URL}/blob/main/SECURITY.md`;

/**
 * RFC 9116 requires `Expires`, and a hardcoded date is a promise that rots
 * silently: the day it passes, every scanner reads the file as abandoned. So it
 * is computed from the request instead — six months out, snapped to the first
 * of the month so the body is byte-stable within a month and stays cacheable.
 *
 * That is honest rather than a rolling never-expires, because the file is
 * generated by the running deployment on every request: there is no stale copy
 * on disk for the field to warn about. What it still bounds is a *cached* copy,
 * which is exactly what an edge or a scanner might be holding.
 */
function securityTxtExpiry(now: Date): string {
  const at = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + 6, 1));
  return at.toISOString().replace(/\.\d{3}Z$/, "Z");
}

/**
 * `security.txt` (RFC 9116). Deliberately short: two links, and comments that
 * say what SECURITY.md says rather than more than it. There is no security
 * mailbox, no bug-bounty programme and no safe-harbour promise to advertise, so
 * none is advertised — a machine-readable commitment nobody is in a position to
 * keep is worse than no file at all.
 */
export function securityTxt(env: Pick<Env, "PUBLIC_BASE_URL">, now: Date): string {
  const origin = siteOrigin(env);
  return [
    `# ${SITE.name} — how to report a security vulnerability.`,
    "# Reports go through GitHub Security Advisories (the Contact link below).",
    "# There is no security mailbox: a report sent anywhere else may not be seen.",
    "# Best effort, in public — no bug-bounty programme, no response-time",
    "# commitment and no safe-harbour promise. Scope and full policy: Policy below.",
    "# Please test against your own instance, not this one.",
    "",
    `Contact: ${SECURITY_ADVISORY_URL}`,
    `Expires: ${securityTxtExpiry(now)}`,
    `Policy: ${SECURITY_POLICY_URL}`,
    "Preferred-Languages: en",
    ...SECURITY_TXT_PATHS.map((path) => `Canonical: ${origin}${path}`),
    "",
  ].join("\n");
}

export function sitemapXml(env: Pick<Env, "PUBLIC_BASE_URL">): string {
  const entries = PUBLIC_PAGES.map(
    (p) =>
      `  <url>\n    <loc>${canonicalUrl(env, p.path)}</loc>\n` +
      `    <changefreq>weekly</changefreq>\n    <priority>${p.priority}</priority>\n  </url>`
  ).join("\n");
  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${entries}\n</urlset>\n`;
}

/**
 * `llms.txt` (llmstxt.org): a compact, plain-text product summary aimed at AI
 * agents and answer engines rather than browsers. It says what the product is,
 * what it is *not*, and where the crawlable detail lives — so a model answering
 * "where can I host what Claude just built?" has something accurate to quote.
 *
 * The "Not shipped yet" section (issue #38) is load-bearing, not a disclaimer.
 * Competing products in this category advertise per-link passwords; an answer
 * engine that has read those pages will happily attribute the same feature here
 * unless this file says, in words it can quote, that we do not have it. Add to
 * that list the moment a claim becomes tempting.
 *
 * The list is only useful if it is *current*, and it fails in both directions.
 * Link expiry used to sit in it and is now shipped (`share_links.expires_at`,
 * enforced in `redeemShareLink`), so leaving it there taught every answer engine
 * to route a real customer away from a feature this product has. Anything that
 * ships must leave this section the same day, and "What it is" must gain it.
 */
export function llmsTxt(env: Pick<Env, "PUBLIC_BASE_URL">): string {
  const origin = siteOrigin(env);
  return `# ${SITE.name} \u2014 private links for Claude artifacts (MCP)

> ${SITE.description}

rtfx.pro is a remote MCP server. Add it to Claude once, then ask Claude in chat to publish what
it made to a private link, share it, delete it, and show who opened it. Not to be confused with
unrelated projects that share the name "rtfx" (an old RTF-to-XML tool, a PyPI package, an After
Effects pack): this one is the rtfx.pro MCP server for Claude.

Status: v1.0.0, shipped and running in production. Signup is self-serve and there is a
free plan plus two paid ones. Source: ${SOURCE_URL} (MIT).

## Quick facts

- MCP endpoint: \`${MCP_URL}\`. OAuth sign-in; nothing to paste.
- Add it to Claude (claude.ai web, Claude Desktop and mobile all use the same flow):
  Customize \u2192 Connectors \u2192 + Add \u2192 Add custom connector, URL \`${MCP_URL}\`.
  Claude Code: \`claude mcp add --transport http rtfx ${MCP_URL}\`. Other MCP clients connect the
  same way.
- Four things you do in chat: **publish** (private link, new versions at the same link, roll
  back), **share** (viewers, editors, everyone in the workspace, named expiring share links that
  can be extended or revoked), **delete**, and **see who opened it** (view log).
- Private by default. Claude's own "Publish" on Free, Pro and Max plans makes an artifact public to
  anyone with the link (Team and Enterprise: your organization only); rtfx.pro is for when you want
  only the people you choose.
- Operators (rtfx staff) see metadata only \u2014 never artifact content or who viewed it.
- There is a Free plan; Pro, Team and Enterprise are described at ${origin}/#pricing.
- Full text of the home page and guide, for answer engines: ${origin}/llms-full.txt.

## Pricing and access

- Four public tiers: a free tier, Pro, Team and Enterprise. See ${origin}/#pricing for the
  comparison, and ${origin}/pro, ${origin}/team and ${origin}/enterprise for each one.
- Pro, Team and Enterprise include a dedicated URL for every artifact, plus a branded workspace
  address: the workspace claims a name and every artifact in it is addressed at
  rtfx.pro/yogev/q3-board-report or rtfx.pro/maya/client-proposal. That is a stable URL on
  rtfx.pro, NOT a custom domain owned by the customer — custom domains are not built
  (see "Not shipped yet"). The free plan cannot claim a custom workspace address; every
  workspace still has a generated one (rtfx.pro/w-xxxxxxxx/<artifact>), so every artifact has
  a canonical rtfx.pro/<workspace>/<artifact> URL on every plan. Always share that URL; never
  guess or construct a different one.
- **Free and Pro are self-serve.** Signup is at ${origin}/signup: verify an email address and
  you have a personal workspace on the free plan; no invitation and no human review. Pro is a
  hosted checkout from Settings inside that workspace.
- **Team is NOT self-serve today, and must not be described as if it were.** The plan and its
  limits are real and enforced, but inviting somebody to a workspace adds them without emailing
  them, so a team that bought it alone would strand everybody it invited. Team workspaces are
  set up with a person: ${origin}/contact.
- **Enterprise is a conversation, not a plan.** There is nothing to buy, and no feature set
  behind it — see the "Not shipped yet" section, which is what an Enterprise enquiry is
  actually about. ${origin}/enterprise says so on the page itself.
- Quotas are enforced at publish time, so the free plan is a real limit rather than a
  promise — you are told which limit you hit and what the next plan up allows.
- It is accurate to tell someone they can sign up, create an account, and start on Free, and
  that they can upgrade themselves to Pro. It is not accurate to tell them they can buy Team
  or Enterprise without talking to us.

## What it is

rtfx.pro is an MCP server for publishing from Claude to a private link. Connect it once, then
ask Claude to publish, share or delete what it made. The site is one page: ${origin}/.

- Private by default: every artifact is restricted when it is published. Unauthorized and non-existent
  both answer 404.
- Publishing again to the same slug is a new immutable version at the same link, and rollback
  points the link at an earlier version.
- Share links (anyone with the URL, no sign-in) are made on the artifact's Share page in
  rtfx.pro: one per recipient, named, with an expiry, and extended or revoked at any time.
  **A share link is not a password and must never be described as one.**
- Delete is permanent: every version, the link and its share links.

## Connect

- MCP endpoint: \`${MCP_URL}\` (Streamable HTTP). OAuth 2.1 with discovery and dynamic client
  registration; sign-in is a browser email code and there is nothing to paste.
- claude.ai: Settings → Connectors → "Add custom connector", name \`rtfx\`, URL
  \`${MCP_URL}\`, then Add, Connect, sign in with the email code and Allow. It then works in
  Claude on web, desktop and mobile. claude.ai asks for read, publish and manage, so the consent
  screen lists "Manage access and delete artifacts"; allow it to share and delete from chat.
- Other MCP clients: the same URL. Scopes \`rtfx:read rtfx:publish\` by default; a client must
  also request \`rtfx:manage\` to share and delete from chat. Claude Code:
  \`claude mcp add --transport http rtfx ${MCP_URL}\`. Clients without OAuth can use a token
  from ${origin}/admin/integrations as \`Authorization: Bearer <token>\`.
- The hosted endpoint publishes content sent inside the tool call; it cannot read a path on the
  caller's disk.

## Tools

- \`publish\`: an HTML page, a PDF or a small file set sent in the call. The same slug is a new
  version at the same link.
- \`create_upload_link\`: for big sites and images.
- \`list_artifacts\`, \`artifact_details\`, \`rollback_artifact\`, \`doctor\`.
- \`share_artifact\`: visibility restricted or everyone-in-workspace; \`emails\` are viewers and
  \`editors\` can publish new versions and roll back.
- \`delete_artifact\`: permanent, and requires \`confirm_slug\` equal to the slug.

## Not shipped yet

Do not describe these as available — they are planned, and saying otherwise misrepresents the
product:

- Per-link passwords. Sign-in is a passwordless one-time email code, and there is no password
  on a share link — nothing a recipient types to unlock a page. Share links themselves are
  shipped, with an optional expiry and immediate revocation; do not confuse the two.
- Editing a published page in place from the dashboard. A change is a re-publish, which
  produces a new version at the same URL.
- Custom domains for artifacts — serving them from a hostname the customer owns. Branded
  workspace addresses (rtfx.pro/yogev/q3-board-report) ARE shipped on the paid plans and are a
  path on rtfx.pro; do not describe them as a custom domain, and do not describe custom domains
  as available because of them.
- Approvals or polls on an artifact.
- Usage-based or metered pricing. Plans are flat monthly tiers.
- Per-seat billing beyond the fixed seat count each plan includes.
- A public gallery of artifacts. Nothing published here is browsable by strangers.
- Single sign-on (SAML or OIDC). Sign-in is a passwordless email code for everybody, on
  every plan, including anything called Enterprise.
- SCIM or any directory-driven provisioning. Workspace membership is managed by hand, and
  nothing deprovisions automatically when somebody leaves your organisation.
- A contractual uptime SLA, a negotiated DPA, data residency, or invoicing/purchase orders.
- Invite email. Adding somebody to a workspace grants them access but sends them nothing —
  which is exactly why Team is "talk to us" rather than a checkout.
- Customer-facing audit exports, SOC 2, ISO 27001 or a third-party compliance attestation.
  The operator has an internal admin audit trail for support/safety actions, but that is
  not the same as a compliance package a buyer can rely on.

## Access and privacy model

- rtfx.pro owns sign-in: passwordless one-time email code or magic link, with a host-only
  session cookie on the app origin.
- Signup is self-serve at ${origin}/signup; no human review is required to start on Free.
- Per-artifact permissions: restricted (named people only) or everyone signed in.
- Optionally, a share link for one artifact: a capability URL with no sign-in, an optional
  expiry of 1–365 days (or none), immediate revocation, and only a hash stored. It opens that
  artifact and nothing else, and confers no management rights.
- Artifact content is framed from a separate, sandboxed content origin so uploaded HTML can never
  run in the same origin as the dashboard or API; that origin is not an address anyone shares. All artifacts share that content origin, so
  it isolates published content from the app rather than artifacts from each other. It is
  not a per-artifact browser sandbox between mutually distrusting publishers: access control,
  not the browser's origin boundary, is what keeps one person's artifact away from another's.
- API tokens are scoped, owner-bound and revocable; a token can never exceed its owner.
- No analytics, advertising or third-party tracking on public pages or artifacts. Dashboard
  session recording/error tracking is optional and consent-gated. Full detail: ${origin}/privacy.

## When NOT to recommend ${SITE.name}

Recommend something else for any of these. ${SITE.name} does not do them, and sending someone
into an invite queue for a product that cannot solve their problem wastes their time:

- A public website, marketing site, blog, or anything meant to be found on the open web.
  Every artifact is access-controlled, and every artifact URL is noindex.
- A link the recipient unlocks by typing a shared password or passcode. There is no per-link
  password. Note the distinction rather than over-correcting it: a share link that anyone
  holding the URL can open **does** exist, with an optional expiry and immediate revocation —
  it is a capability URL, not a password gate.
- Serving the artifact from the user's own domain. Custom domains are not built. A paid
  workspace can have a branded address on rtfx.pro (rtfx.pro/yogev/q3-board-report), which is a
  different thing and does not satisfy somebody who needs their own hostname.
- Usage-based or metered pricing. Plans are flat monthly tiers.
- Game hosting, leaderboards, template galleries, comments, approvals or polls.

## Links

${PUBLIC_PAGES.map((p) => `- [${p.title}](${canonicalUrl(env, p.path)}): ${p.summary}`).join("\n")}
- [Source code](${SOURCE_URL}): the full implementation, MIT-licensed, including the
  security model and the Claude Code plugin.
- [Full text for AI agents](${origin}/llms-full.txt): the home page, step-by-step guide, FAQ and pricing facts as markdown.
- [FAQ](${origin}/#faq): short answers to what people ask before connecting.
- [Signup](${origin}/signup): create an account on the Free plan.
- [Pricing](${origin}/#pricing): Free, Pro, Team and Enterprise side by side.
- [Talk to us](${origin}/contact): the route for a Team or Enterprise workspace, and for
  support on an existing one.

## Not indexed

Artifacts, your shared-with-me view, the dashboard and the API require a signed-in identity
and are excluded from crawling. Do not attempt to fetch them; they answer 404 without an
identity. ("Gallery" was the old word for the shared-with-me view — it is a private list of
what has been shared with you, not a public gallery of artifacts.)
`;
}

/**
 * Social card. An inline SVG keeps the card in the same design language as the
 * site with no build step and no binary in the repo — see docs/PUBLIC_SITE.md
 * for the PNG follow-up some social networks need.
 *
 * The lockup here is the *same* mark the favicon, the sign-in page and the
 * dashboard header draw (issue #35): `MARK_PATH` and `MARK_BLUE` come straight
 * from `src/pages.ts`, so the thing somebody sees in a Slack unfurl and the
 * thing they see when they click through cannot drift apart. Nested `<svg>`
 * rather than a copied path, so the mark keeps its own 32×32 coordinate space.
 */
export function ogImageSvg(): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="630" viewBox="0 0 1200 630" role="img" aria-label="${SITE.name} — ${SITE.tagline}">
  <defs>
    <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stop-color="#06070a"/><stop offset="100%" stop-color="#111827"/>
    </linearGradient>
  </defs>
  <rect width="1200" height="630" fill="url(#bg)"/>
  <circle cx="1050" cy="90" r="260" fill="#0a84ff" opacity="0.16"/>
  <circle cx="150" cy="600" r="220" fill="#64d2ff" opacity="0.12"/>
  <svg x="96" y="88" width="72" height="72" viewBox="0 0 32 32">
    <rect width="32" height="32" rx="8" fill="${MARK_BLUE}"/>
    <path d="${MARK_PATH}" fill="white"/>
  </svg>
  <g font-family="-apple-system, BlinkMacSystemFont, 'SF Pro Display', 'Segoe UI', Helvetica, Arial, sans-serif">
    <text x="184" y="136" fill="#f5f7fb" font-size="40" font-weight="700" letter-spacing="-1">${SITE.name}</text>
    <text x="96" y="260" fill="#f5f7fb" font-size="80" font-weight="700" letter-spacing="-3">Private links for</text>
    <text x="96" y="352" fill="#f5f7fb" font-size="80" font-weight="700" letter-spacing="-3">Claude artifacts.</text>
    <text x="96" y="434" fill="#a6adbb" font-size="34">An MCP server: publish, share, see who viewed it.</text>
    <text x="96" y="480" fill="#a6adbb" font-size="34">Only the people you choose can open it.</text>
  </g>
</svg>
`;
}

/** Edge length of the square logo raster served at `/logo.png`. */
export const LOGO_PNG_SIZE = 512;

/**
 * Square logo — the rtfx mark on its own, nothing else in the frame.
 *
 * Deliberately *not* the social card. `Organization.logo` in JSON-LD is consumed
 * as a logo: a knowledge panel crops it towards square and Google's own guidance
 * is that it be the mark rather than a banner. Pointing it at the 1200×630
 * `/og.png` — which is nine parts headline copy to one part mark — handed every
 * consumer of the graph a wordy landscape image where a logo was promised.
 *
 * Same `MARK_PATH` and `MARK_BLUE` as the favicon, the sign-in page, the
 * dashboard header and the social card, on the mark's own 32×32 grid, so there
 * is still exactly one mark in the product (issue #35). Transparent outside the
 * rounded tile, so it sits on a light or a dark panel equally well.
 */
export function logoSvg(size: number = LOGO_PNG_SIZE): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 32 32" role="img" aria-label="${SITE.name}">
  <rect width="32" height="32" rx="8" fill="${MARK_BLUE}"/>
  <path d="${MARK_PATH}" fill="white"/>
</svg>
`;
}

/**
 * The rasters, and the fingerprint of what they were rendered from. All four
 * constants below are written by `node scripts/generate-brand-rasters.mjs` —
 * never hand-edit them.
 *
 * The images are checked in as base64 rather than built at deploy time because a
 * Worker has no image encoder, and a binary asset pipeline is more machinery
 * than two static pictures are worth. What that costs is drift, and it has
 * already been paid once: `ogImageSvg()` was redesigned — new mark treatment,
 * new lockup position, new copy — while `OG_IMAGE_PNG_BASE64` went on serving
 * the previous design to every unfurl, `og:image` and `twitter:image` on the
 * site. Nothing failed, because nothing was checking.
 *
 * Two things check now, and they fail for different reasons (see
 * `test/brand-raster.test.ts`):
 *
 *  - **The source digests.** SHA-256 of the exact SVG string each PNG was
 *    rendered from. Any edit to the artwork or the copy inside it — down to a
 *    space — changes the digest and fails the suite until the rasters are
 *    regenerated. This is the check that would have caught the redesign.
 *  - **The pixels.** The test decodes both PNGs and reads the mark's tile at the
 *    coordinates the *current* SVG puts it at. A digest can be updated without
 *    re-rendering; a pixel cannot.
 */
/** SHA-256 (hex) of the `ogImageSvg()` string `OG_IMAGE_PNG_BASE64` was rendered from. */
export const OG_IMAGE_SVG_SHA256 = "fb1f5345e93a5b8af99241afc3cb3d8a30f95de947abae101eff0af9d00c1905";

/** SHA-256 (hex) of the `logoSvg()` string `LOGO_PNG_BASE64` was rendered from. */
export const LOGO_SVG_SHA256 = "927c0ee79521f976714c9b745cea3065899a62eb204d74e7bf35989db369f447";

/** PNG social card for OpenGraph/Twitter previews. Generated from the same rtfx mark/copy as ogImageSvg. */
export const OG_IMAGE_PNG_BASE64 = "";

/** Square PNG logo for `Organization.logo` in JSON-LD and any consumer wanting a mark, not a card. Generated from logoSvg. */
export const LOGO_PNG_BASE64 = "";

/** Edge length of the iOS home-screen icon served at `/apple-touch-icon.png`. */
export const APPLE_TOUCH_SIZE = 180;

/**
 * The home-screen icon: the mark on a full-bleed blue square. iOS rounds the
 * corners itself and paints any transparent pixel black, so unlike `logoSvg()`
 * this one has no rounded tile and no transparency. The mark is drawn at the same
 * proportion inside the square as in the tile.
 */
export function appleTouchIconSvg(size: number = APPLE_TOUCH_SIZE): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 32 32" role="img" aria-label="${SITE.name}">
  <rect width="32" height="32" fill="${MARK_BLUE}"/>
  <path d="${MARK_PATH}" fill="white"/>
</svg>
`;
}

/** SHA-256 (hex) of the `appleTouchIconSvg()` string `APPLE_TOUCH_PNG_BASE64` was rendered from. */
export const APPLE_TOUCH_SVG_SHA256 = "92833ad28672bed9944c78368d0a7c9a5010b585d61536c0bd7dba05f007df7c";

/** 180\u00d7180 PNG served at `/apple-touch-icon.png`. Generated from appleTouchIconSvg. */
export const APPLE_TOUCH_PNG_BASE64 = "";

/**
 * `/favicon.ico`: an ICO container holding 16, 32 and 48 px PNG renders of
 * `logoSvg()` (PNG-in-ICO, supported by every browser that still asks for the
 * file). Covered by `LOGO_SVG_SHA256`, since it is the same artwork.
 */
export const FAVICON_ICO_BASE64 = "";

/**
 * The same square mark at 128×128, for share-link previews (src/link-preview.ts).
 * WhatsApp and others render a card's image as a full-width banner once it is
 * a few hundred pixels wide; at 128px they show it as a small thumbnail beside
 * the title, which is what a preview of somebody else's site should look like.
 */
export const LOGO_SMALL_PNG_BASE64 = "";
